// Blocking: 한 번에 10억 번 돌기 (화면 멈춤!)
function heavy() {
  for (let i = 0; i < 1000000000; i++) {}
}

// Non-blocking: 잘게 쪼개서 실행 (Yielding)
let i = 0;
function heavyChunk() {
  // 1. 조금만 함
  const end = i + 1000000;
  while (i < end) { i++; }

  // 2. 나머지는 다음 틱으로 양보 (Yield)
  if (i < 1000000000) {
    setTimeout(heavyChunk, 0);
  }
}
